using namespace std;

// Apply backspaces with a stack: '#' pops the last kept character if any.
static string process(const string &s) {
    string st;
    for (char c : s) {
        if (c == '#') { if (!st.empty()) st.pop_back(); }
        else if (c != '\r') st.push_back(c);
    }
    return st;
}

