import java.io.*;

public class Main {
    // Apply backspaces with a stack: '#' pops the last kept character if any.
    static String process(String s) {
        StringBuilder st = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '#') { if (st.length() > 0) st.setLength(st.length() - 1); }
            else st.append(c);
        }
        return st.toString();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String a = br.readLine(), b = br.readLine();
        System.out.println(process(a).equals(process(b)) ? 1 : 0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// Apply backspaces with a stack: '#' pops the last kept character if any.
func process(s string) string {
	st := make([]byte, 0, len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == '#' {
			if len(st) > 0 {
				st = st[:len(st)-1]
			}
		} else {
			st = append(st, s[i])
		}
	}
	return string(st)
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	a, _ := in.ReadString('\n')
	b, _ := in.ReadString('\n')
	a, b = strings.TrimRight(a, "\r\n"), strings.TrimRight(b, "\r\n")
	if process(a) == process(b) {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}
